def test_hypothesis(inp, out):
    """Test if each non-zero value moves to maintain Row+col diagonal"""
    print("Hypothesis: Each non-2 value maintains Row+col diagonal")

    for r in range(len(inp)):
        for c in range(len(inp[0])):
            inp_val = inp[r][c]
            if inp_val != 0 and inp_val != 2:
                inp_sum = r + c
                # Find all cells in output with Row+col = inp_sum
                out_positions = []
                for r_out in range(len(out)):
                    for c_out in range(len(out[0])):
                        if out[r_out][c_out] == inp_val and r_out + c_out == inp_sum:
                            out_positions.append((r_out, c_out))

                if out_positions:
                    print(f"  Input ({r},{c})={inp_val}, Row+col={inp_sum} → Output at {out_positions}")
                else:
                    print(f"  Input ({r},{c})={inp_val}, Row+col={inp_sum} → Output has NO cells at sum={inp_sum}")

